-- Blog: presente de Natal com a Arca.
insert into public.ara_posts (slug,titulo,subtitulo,resumo,conteudo,ilustracao,foto_url,publicado,data,ordem,seo_titulo,seo_descricao) values ('presente-de-natal-diferente-arca','Presente de Natal diferente: a Arca, um presente que ninguém mais vai dar','Uma obra de cristais criada à mão com o nome e a data de nascimento de quem você ama. Como escolher e encomendar a tempo do Natal.','Procurando um presente de Natal diferente e com significado? Conheça a Arca: uma obra exclusiva de cristais, criada à mão com o nome e a data de nascimento de quem vai receber.','<p>Todo fim de ano é igual: a lista de presentes cresce, o tempo diminui e a gente acaba comprando mais do mesmo. Perfume, vinho, mais uma peça de roupa. Presentes que agradam no dia e somem em uma semana. Se você procura um <strong>presente de Natal diferente</strong>, que a pessoa guarde para sempre, este guia é para você.</p>
<h2>O que faz um presente ser inesquecível</h2>
<p>Quase todo mundo lembra de um presente que marcou. E quase nunca é o mais caro. É o que mostrou que alguém <strong>pensou em você</strong>: no seu nome, na sua história, no que você estava vivendo. Um presente com significado diz "eu te vejo", e isso nenhuma loja de departamento vende.</p>
<h2>A Arca: um presente que não existe em nenhum outro lugar</h2>
<p>A <strong>Arca</strong> da ARA é uma obra exclusiva, criada à mão a partir do <strong>nome completo e da data de nascimento</strong> de quem vai receber. Cada cristal é escolhido um a um para aquela pessoa e reunido em um só lugar, entre madeira orgânica e vidro, com acabamento especial. É um altar particular, para a sala, o quarto ou a mesa de trabalho.</p>
<p>Cristais não se repetem. Nenhuma Arca também. Por isso ela é o tipo de presente que ninguém mais vai dar.</p>
<figure><img src="/img/arca-essencial-colecao.160e871b.jpg" alt="Arca Essencial da ARA, obra de cristais naturais em madeira orgânica e vidro" width="1400" height="1050" loading="lazy"><figcaption>Arca Essencial. Imagem ilustrativa.</figcaption></figure>
<h2>Para quem a Arca é o presente certo</h2>
<ul>
<li><strong>Para a mãe, a avó, a madrinha:</strong> quem já tem tudo, mas não tem uma obra feita com o próprio nome.</li>
<li><strong>Para quem está começando uma fase nova:</strong> casa nova, trabalho novo, um recomeço. A Arca marca o momento.</li>
<li><strong>Para quem gosta de cristais, meditação ou espiritualidade:</strong> um altar pronto, organizado e protegido da poeira.</li>
<li><strong>Para quem gosta de decoração:</strong> uma peça única, que vira ponto de atenção em qualquer ambiente.</li>
<li><strong>Para o seu amor:</strong> um presente que diz que você prestou atenção.</li>
</ul>
<h2>Como funciona a encomenda</h2>
<ol>
<li><strong>Escolha o modelo</strong> na <a href="/arca#colecao">coleção da Arca</a>: Essencial, Plena ou Ateliê.</li>
<li><strong>Envie o nome completo e a data de nascimento</strong> de quem vai receber. Se quiser, conte um pouco sobre a pessoa ou a intenção do presente.</li>
<li><strong>A ARA cria a obra à mão</strong>, escolhendo cada cristal para aquela pessoa.</li>
<li><strong>Entrega:</strong> na Grande São Paulo, pelo Motoboy Express ou pela coleta; para o resto do Brasil, combinado pelo WhatsApp.</li>
</ol>
<p>A Essencial e a Plena levam cerca de <strong>4 dias</strong> para serem criadas. A Ateliê, com a estrutura feita sob encomenda, cerca de <strong>40 dias</strong>. Para chegar antes do Natal sem correria, <strong>encomende com antecedência</strong>: dezembro é o mês mais disputado.</p>
<h2>Os três modelos</h2>
<ul>
<li><strong>Arca Essencial</strong> (30 × 16 × 8,5 cm): o seu altar particular em formato compacto. Cabe na estante, na cabeceira ou na mesa de trabalho. A partir de R$ 1.200, em até 10x.</li>
<li><strong>Arca Plena</strong> (36 × 21 × 12 cm): mais espaço para a história da pessoa, com mais cristais e mais camadas.</li>
<li><strong>Arca Ateliê</strong>: a expressão máxima da Arca, com a estrutura também feita à mão.</li>
</ul>
<p>Veja fotos, medidas e valores de cada uma na <a href="/arca#colecao">página da Arca</a>.</p>
<figure><img src="/img/arca-ambiente-sala.12e14bc2.jpg" alt="Arca de cristais sobre a mesa de centro da sala" width="1374" height="1145" loading="lazy"><figcaption>Ambientação ilustrativa.</figcaption></figure>
<h2>Presentes menores, com o mesmo cuidado</h2>
<p>Para o amigo secreto ou para completar o presente, a loja tem cristais escolhidos à mão, um a um:</p>
<ul>
<li><a href="/loja/aura-da-prosperidade">Aura da Prosperidade</a>, com pirita, para quem está começando um projeto.</li>
<li><a href="/loja/aura-da-calma">Aura da Calma</a>, com ametista, para quem precisa desacelerar.</li>
<li><a href="/loja/aura-da-clareza">Aura da Clareza</a>, com cristal de quartzo, para um começo de ano com clareza.</li>
</ul>
<p>Mais ideias em <a href="/blog/presente-espiritual-personalizado">presente espiritual personalizado</a>.</p>
<h2>Garanta a Arca do seu Natal</h2>
<p>Cada Arca é única e feita à mão, uma de cada vez. <a href="/arca#colecao">Escolha o modelo</a> ou <a href="https://wa.me/5511973371416?text=Ol%C3%A1!%20Quero%20uma%20Arca%20de%20presente%20de%20Natal." target="_blank" rel="noopener">fale com a ARA pelo WhatsApp</a> e conte para quem é o presente. A gente ajuda você a escolher.</p>','rosa','',true,'2026-10-21',-6,'Presente de Natal diferente e com significado | ARA','Presente de Natal diferente: a Arca, obra exclusiva de cristais criada à mão com o nome e a data de nascimento de quem você ama. Em até 10x.') on conflict (slug) do update set titulo=excluded.titulo, subtitulo=excluded.subtitulo, resumo=excluded.resumo, conteudo=excluded.conteudo, ilustracao=excluded.ilustracao, foto_url=excluded.foto_url, publicado=excluded.publicado, data=excluded.data, ordem=excluded.ordem, seo_titulo=excluded.seo_titulo, seo_descricao=excluded.seo_descricao, atualizado_em=now();
